// /xemtruoc <số> [giờ]  -> act xemtruoc (đăng ẨN Fanpage + Zalo OA)
// /congkhai <số> [giờ|huy] -> act congkhai (công khai ngay) | capnhat (hẹn giờ / bỏ hẹn)
// Mỗi 5 phút: bài "Chờ công khai" đến giờ -> act congkhai
// Bản ẩn lưu trong Ghi chú: [ẨN fb=<id> oa=<id> h=<mã nội dung+ảnh>]
const ZONE = 'Asia/Ho_Chi_Minh';
const GROUP = '<ZALO_GROUP_ID>', OA = '<ZALO_OA_ID>';
let cmd = null; try { if ($('Khi được gọi').isExecuted) cmd = $('Khi được gọi').first().json; } catch (e) {}
const rows = $('Đọc lịch đăng').all().map(i => i.json).filter(r => r && r['ID']);
const H = (s) => { let x = 5381; for (const ch of String(s || '')) x = ((x * 33) ^ ch.charCodeAt(0)) >>> 0; return x.toString(36); };
const maBai = (r) => H(['Nội dung', 'Link ảnh', 'Ảnh thêm', 'Ảnh bìa OA', 'Ảnh Zalo'].map(k => String(r[k] || '').trim()).join('|'));
const TAG = /\s*\|?\s*\[ẨN fb=(\S*) oa=(\S*) h=([a-z0-9]*)\]/;
const st = (r) => String(r['Trạng thái'] || '').trim();
const now = DateTime.now().setZone(ZONE);
const nowS = now.toFormat('dd/MM/yyyy HH:mm');
function docGio(s) {
  s = String(s || '').toLowerCase().trim();
  if (!s) return null;
  if (/^(huy|hủy|xoa|xóa|bo|bỏ)$/.test(s)) return '';
  const m = s.match(/(\d{1,2})\s*(?:h|giờ|g|:)\s*(\d{1,2})?/);
  if (!m) return 'loi';
  const Hh = +m[1], M = +(m[2] || 0);
  if (Hh > 23 || M > 59) return 'loi';
  const dm = s.match(/(\d{1,2})\s*[\/\-.]\s*(\d{1,2})(?:\s*[\/\-.]\s*(\d{2,4}))?/);
  let d = now;
  if (dm) { const y = dm[3] ? (dm[3].length === 2 ? 2000 + +dm[3] : +dm[3]) : now.year; d = DateTime.fromObject({ year: y, month: +dm[2], day: +dm[1] }, { zone: ZONE }); if (!d.isValid) return 'loi'; }
  else if (/mai/.test(s)) d = now.plus({ days: 1 });
  let t = d.set({ hour: Hh, minute: M, second: 0, millisecond: 0 });
  if (!dm && !/mai/.test(s) && t <= now.plus({ minutes: 1 })) t = t.plus({ days: 1 });
  if (t <= now) return 'qua';
  return t.toFormat('d/M/yyyy H:mm');
}
const GIO_HD = 'Ví dụ giờ: "20:15" (hôm nay, qua rồi thì mai), "20h", "9h30 mai", "8:00 16/11".';
function docThoiGian(v) { for (const f of ['d/M/yyyy H:mm', 'd/M/yyyy H:mm:ss', 'yyyy-MM-dd H:mm']) { const d = DateTime.fromFormat(String(v || '').trim(), f, { zone: ZONE }); if (d.isValid) return d; } return null; }
const tra = (reply) => [{ json: { act: 'traloi', reply, group_id: cmd?.group_id || GROUP } }];
const thongTin = (r) => { const m = String(r['Ghi chú'] || '').match(TAG); return m ? { fb: m[1], oa: m[2], h: m[3] } : null; };
// ----- lượt 5 phút: công khai bài hẹn giờ đã đến giờ
if (!cmd) {
  const r = rows.find(r => st(r) === 'Chờ công khai' && docThoiGian(r['Thời gian đăng']) && docThoiGian(r['Thời gian đăng']) <= now);
  if (!r) return [];
  const t = thongTin(r); if (!t) return [];
  return [{ json: { act: 'congkhai', id: String(r['ID']), row: r, fb: t.fb, oa: t.oa, group_id: GROUP, oa_id: OA, hen: true } }];
}
const id = String(cmd.id);
const row = rows.find(r => String(r['ID']) === id);
if (!row) return tra(`❌ Không tìm thấy bài #${id} trong lịch đăng.`);
const s0 = st(row);
if (cmd.route === 'xemtruoc') {
  if (s0 !== 'Chờ duyệt') return tra(`ℹ️ Bài #${id} đang "${s0 || 'trống'}". /xemtruoc chỉ dùng cho bài Chờ duyệt.`);
  if (!String(row['Nội dung'] || '').trim()) return tra(`ℹ️ Bài #${id} chưa có nội dung.`);
  if (!String(row['Link ảnh'] || '').trim()) return tra(`⚠️ Bài #${id} chưa có ảnh chính. Gửi ảnh rồi gõ /datanh ${id} (hoặc /dunganh ${id}).`);
  const bia = String(row['Ảnh bìa OA'] || '').trim();
  if (!bia) return tra(`⚠️ Bài #${id} chưa có ảnh bìa Zalo OA. Gửi 1 ảnh ngang + /dunganh ${id}, hoặc gõ /anhbia ${id}.`);
  const src = (bia.match(/#src=([a-z0-9]+)/) || [])[1];
  if (src && src !== H(String(row['Link ảnh']).trim())) return tra(`⚠️ Ảnh bìa Zalo OA của bài #${id} làm từ ảnh chính cũ. Gõ /anhbia ${id} để làm lại rồi /xemtruoc ${id}.`);
  let gio = null;
  if (cmd.gio) { gio = docGio(cmd.gio); if (gio === 'loi' || gio === '') return tra(`ℹ️ Chưa hiểu giờ "${cmd.gio}".\n${GIO_HD}`); if (gio === 'qua') return tra(`ℹ️ Giờ "${cmd.gio}" đã qua rồi.`); }
  const t = thongTin(row) || {};
  return [{ json: { act: 'xemtruoc', id, row, gio, fbCu: t.fb || '', oaCu: t.oa || '', ma: maBai(row), group_id: cmd.group_id, oa_id: OA } }];
}
// ----- /congkhai
if (!['Chờ duyệt', 'Chờ công khai'].includes(s0)) return tra(`ℹ️ Bài #${id} đang "${s0 || 'trống'}" nên không công khai được.`);
const t = thongTin(row);
if (!t || !t.fb) return tra(`ℹ️ Bài #${id} chưa đăng ẩn để xem trước. Gõ /xemtruoc ${id} trước, xem ưng rồi mới /congkhai ${id}.\n(Hoặc /duyet ${id} để đăng theo cách cũ.)`);
if (t.h !== maBai(row)) return tra(`⚠️ Bài #${id} đã sửa chữ/ảnh sau lần xem trước nên bản ẩn đang cũ.\n👀 Gõ /xemtruoc ${id} để đăng ẩn bản mới, xem lại rồi /congkhai ${id}.`);
const gio = docGio(cmd.gio);
if (gio === 'loi') return tra(`ℹ️ Chưa hiểu giờ "${cmd.gio}".\n${GIO_HD}\nGõ /congkhai ${id} (công khai ngay) hoặc /congkhai ${id} huy (bỏ hẹn giờ).`);
if (gio === 'qua') return tra(`ℹ️ Giờ "${cmd.gio}" đã qua rồi, chọn giờ khác (hoặc /congkhai ${id} để công khai ngay).`);
const ghi = (s) => `${String(row['Ghi chú'] || '').trim()} | ${s}`.replace(/^ \| /, '');
if (gio === '') {
  if (s0 !== 'Chờ công khai') return tra(`ℹ️ Bài #${id} chưa hẹn giờ công khai.`);
  return [{ json: { act: 'capnhat', id, row, group_id: cmd.group_id, update: { 'ID': id, 'Trạng thái': 'Chờ duyệt', 'Thời gian đăng': '', 'Ghi chú': ghi(`Bỏ hẹn công khai qua Zalo ${nowS}`) },
    reply: `⏰ Đã bỏ hẹn giờ công khai bài #${id}. Bài vẫn đang ẩn (Chờ duyệt).\n✅ Công khai: /congkhai ${id} [giờ] · ✏️ Sửa rồi /xemtruoc ${id} lại.` } }];
}
if (gio) return [{ json: { act: 'capnhat', id, row, group_id: cmd.group_id, update: { 'ID': id, 'Trạng thái': 'Chờ công khai', 'Thời gian đăng': gio, 'Ghi chú': ghi(`Hẹn công khai ${gio} qua Zalo ${nowS}`) },
  reply: `⏰ Bài #${id} sẽ tự CÔNG KHAI lúc ${gio} (Fanpage + Zalo OA, có thể trễ tối đa ~5 phút).\n🔁 Đổi giờ: /congkhai ${id} <giờ> · Công khai ngay: /congkhai ${id} · Bỏ hẹn: /congkhai ${id} huy · Bỏ bài: /bo ${id}` } }];
return [{ json: { act: 'congkhai', id, row, fb: t.fb, oa: t.oa, group_id: cmd.group_id, oa_id: OA } }];

// Dữ liệu bài từ Sheet (giống Tự động đăng): nội dung + chữ ký; Fanpage bỏ dòng [ảnh N]
const x = $('Xử lý lệnh').first().json; const r = x.row;
const FOOTER = "---***---
CÔNG TY TNHH GOSTECH
Giải pháp phát triển doanh nghiệp
📍 Trụ sở chính: Số nhà 11, ngõ 245/116/27 Phố Định Công, Phường Định Công, Hà Nội
