🌐 Website: gostech.vn | hocviendigital.vn";
const s0 = String(r['Nội dung'] || '').trim();
const noiDung = s0.includes('CÔNG TY TNHH GOSTECH') ? s0 : s0 + '

' + FOOTER;
const MK = /^\[\s*(?:ảnh|anh|hình|hinh)\s*([0-9][0-9 ,+&và]*)\]$/iu;
const noiDungFb = noiDung.split('
').filter(l => !MK.test(l.trim())).join('
').replace(/
{3,}/g, '

');
return [{ json: { id: Number(x.id), noiDung, noiDungFb, linkAnh: String(r['Link ảnh'] || '').trim(), 'Ảnh thêm': String(r['Ảnh thêm'] || '').trim(),
  anhThem: String(r['Ảnh thêm'] || '').trim(), anhBia: String(r['Ảnh bìa OA'] || '').trim(), anhZalo: String(r['Ảnh Zalo'] || '').trim(), note: '', oa_id: x.oa_id, group_id: x.group_id } }];

// Ảnh chính + ảnh thêm (tối đa 10) -> mỗi ảnh 1 item để tải ẩn lên Trang.
// Ảnh NGANG xếp lên đầu (Facebook đặt ảnh đầu tiên to ở trên: kiểu 1 ngang + 2-3 vuông)
const p = $input.first().json;
// ảnh thêm gắn #zalo chỉ dùng cho Zalo -> bỏ; #fb chỉ dùng cho Fanpage -> giữ (bỏ nhãn)
const all = [p.linkAnh, ...String(p['Ảnh thêm'] || '').split('\n').map(s => s.trim()).filter(s => s && !/#zalo$/i.test(s)).map(s => s.replace(/#fb$/i, ''))].filter(Boolean).slice(0, 10);
function size(b) {
  if (b[0] === 0x89 && b[1] === 0x50) return { width: b.readUInt32BE(16), height: b.readUInt32BE(20) };            // PNG
  if (b.toString('ascii', 0, 3) === 'GIF') return { width: b.readUInt16LE(6), height: b.readUInt16LE(8) };          // GIF
  if (b.toString('ascii', 0, 4) === 'RIFF' && b.toString('ascii', 8, 12) === 'WEBP') {                             // WebP
    const t = b.toString('ascii', 12, 16);
    if (t === 'VP8X') return { width: 1 + b.readUIntLE(24, 3), height: 1 + b.readUIntLE(27, 3) };
    if (t === 'VP8 ') return { width: b.readUInt16LE(26) & 0x3fff, height: b.readUInt16LE(28) & 0x3fff };
    if (t === 'VP8L') { const n = b.readUInt32LE(21); return { width: (n & 0x3fff) + 1, height: ((n >> 14) & 0x3fff) + 1 }; }
  }
  if (b[0] === 0xff && b[1] === 0xd8) {                                                                              // JPEG: tìm khung SOF
    let i = 2;
    while (i < b.length - 9) {
      if (b[i] !== 0xff) { i++; continue; }
      const m = b[i + 1];
      if (m >= 0xc0 && m <= 0xcf && ![0xc4, 0xc8, 0xcc].includes(m)) return { width: b.readUInt16BE(i + 7), height: b.readUInt16BE(i + 5) };
      if (m === 0xd8 || m === 0x01 || (m >= 0xd0 && m <= 0xd7)) { i += 2; continue; }
      i += 2 + b.readUInt16BE(i + 2);
    }
  }
